import numpy as np

def get_s(grid):
    rows, cols = grid.shape
    sums = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            s = grid[r, c] + grid[r+1, c] + grid[r, c+1] + grid[r+1, c+1]
            sums.append(s)
    return sums

def solve(N):
    # Try all configurations of a given k
    # But we want to find the maximum k that is stuck.
    # Let's just find all stuck configurations.
    # A configuration is stuck if it's not all 1s and its Rule-2 component has no S=3.

    # We can represent the grid as an integer from 0 to 2^(N*N)-1.
    # For N=3, 2^9 = 512. For N=4, 2^16 = 65536.

    num_configs = 2**(N*N)
    adj = [[] for _ in range(num_configs)]
    for i in range(num_configs):
        grid = np.zeros((N, N), dtype=int)
        for j in range(N*N):
            if (i >> j) & 1:
                grid[j // N, j % N] = 1

        sums = get_s(grid)
        for idx, s in enumerate(sums):
            if s == 2:
                r, c = idx // (N-1), idx % (N-1)
                # Rule 2: flip the 2x2 block at (r,c)
                new_grid = grid.copy()
                new_grid[r:r+2, c:c+2] = 1 - new_grid[r:r+2, c:c+2]
                new_idx = 0
                for r_idx in range(N):
                    for c_idx in range(N):
                        if new_grid[r_idx, c_idx]:
                            new_idx += 2**(r_idx * N + c_idx)
                adj[i].append(new_idx)

    # Now find components and check if they contain S=3
    visited = [False] * num_configs
    max_k = -1

    for i in range(num_configs):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            has_s3 = False

            while stack:
                u = stack.pop()
                component.append(u)

                # Check if u has any S=3
                grid_u = np.zeros((N, N), dtype=int)
                for j in range(N*N):
                    if (u >> j) & 1:
                        grid_u[j // N, j % N] = 1

                if 3 in get_s(grid_u):
                    has_s3 = True

                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

            # A component is stuck if it's not all 1s and it has no S=3
            # But wait, a component could contain the all-1s state.
            # If the component contains all-1s, then it's not stuck.

            is_all_1s = any(u == num_configs - 1 for u in component)

            if not has_s3 and not is_all_1s:
                # This component is stuck.
                # The k values in this component are the number of 1s.
                for u in component:
                    k = bin(u).count('1')
                    if k > max_k:
                        max_k = k

    return max_k + 1

