def solve_max_k_strict(n):
    max_k = 0
    import itertools
    for cells in itertools.product([0, 1], repeat=n*n):
        grid = [cells[i*n:(i+1)*n] for i in range(n)]
        valid = True
        for i in range(n-1):
            for j in range(n-1):
                s = grid[i][j] + grid[i+1][j] + grid[i][j+1] + grid[i+1][j+1]
                if s not in [0, 1, 4]:
                    valid = False
                    break
            if not valid: break
        if valid:
            k = sum(cells)
            if k < n*n:
                max_k = max(max_k, k)
    return max_k

