import numpy as np
from itertools import combinations

def get_s(grid):
    sums = []
    for r in range(grid.shape[0] - 1):
        for c in range(grid.shape[1] - 1):
            s = grid[r, c] + grid[r+1, c] + grid[r, c+1] + grid[r+1, c+1]
            sums.append(s)
    return sums

def is_stuck(grid, N):
    visited = set()
    stack = [tuple(grid.flatten())]
    visited.add(tuple(grid.flatten()))

    has_s3 = False
    is_all_1s = False

    while stack:
        curr_flat = list(stack.pop())
        curr_grid = np.array(curr_flat).reshape((N, N))

        if 3 in get_s(curr_grid):
            has_s3 = True
            break
        if np.all(curr_grid == 1):
            is_all_1s = True
            break

        sums = get_s(curr_grid)
        for idx, s in enumerate(sums):
            if s == 2:
                r, c = idx // (N-1), idx % (N-1)
                new_grid = curr_grid.copy()
                new_grid[r:r+2, c:c+2] = 1 - new_grid[r:r+2, c:c+2]
                new_flat = tuple(new_grid.flatten())
                if new_flat not in visited:
                    visited.add(new_flat)
                    stack.append(new_flat)

    return not has_s3 and not is_all_1s

for cells in combinations(range(9), 4):
    grid = np.zeros((3, 3), dtype=int)
    for c in cells:
        grid[c // 3, c % 3] = 1
    if is_stuck(grid, 3):
        print(f"Stuck configuration for N=3, k=4: {grid}")
        break

