def solve(N):
    if N == 1: return 1
    num_configs = 2**(N*N)
    adj = [[] for _ in range(num_configs)]
    for i in range(num_configs):
        grid = np.zeros((N, N), dtype=int)
        for j in range(N*N):
            if (i >> j) & 1:
                grid[j // N, j % N] = 1
        sums = get_s(grid)
        for idx, s in enumerate(sums):
            if s == 2:
                r, c = idx // (N-1), idx % (N-1)
                new_grid = grid.copy()
                new_grid[r:r+2, c:c+2] = 1 - new_grid[r:r+2, c:c+2]
                new_idx = 0
                for r_idx in range(N):
                    for c_idx in range(N):
                        if new_grid[r_idx, c_idx]:
                            new_idx += 2**(r_idx * N + c_idx)
                adj[i].append(new_idx)
    visited = [False] * num_configs
    max_k = -1
    for i in range(num_configs):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            has_s3 = False
            while stack:
                u = stack.pop()
                component.append(u)
                grid_u = np.zeros((N, N), dtype=int)
                for j in range(N*N):
                    if (u >> j) & 1:
                        grid_u[j // N, j % N] = 1
                if 3 in get_s(grid_u):
                    has_s3 = True
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            is_all_1s = any(u == num_configs - 1 for u in component)
            if not has_s3 and not is_all_1s:
                for u in component:
                    k = bin(u).count('1')
                    if k > max_k:
                        max_k = k
    return max_k + 1

