import itertools

def solve_4x4(k_test):
    squares = []
    for r in range(3):
        for c in range(3):
            squares.append((r*4+c, r*4+c+1, (r+1)*4+c, (r+1)*4+c+1))

    def get_next_states_4x4(grid):
        next_states = []
        for sq in squares:
            vals = [grid[i] for i in sq]
            count = sum(vals)
            if count == 3:
                new_grid = list(grid)
                for i in sq:
                    if new_grid[i] == 0:
                        new_grid[i] = 1
                        next_states.append(tuple(new_grid))
                        break
            elif count == 2:
                new_grid = list(grid)
                for i in sq:
                    new_grid[i] = 1 - new_grid[i]
                next_states.append(tuple(new_grid))
        return list(set(next_states))

    def can_reach_full_4x4(grid):
        visited = set()
        queue = [grid]
        visited.add(grid)
        while queue:
            curr = queue.pop(0)
            if sum(curr) == 16:
                return True
            next_states = get_next_states_4x4(curr)
            for n in next_states:
                if n not in visited:
                    visited.add(n)
                    queue.append(n)
        return False

    for config in itertools.combinations(range(16), k_test):
        grid = [0]*16
        for i in config:
            grid[i] = 1
        if not can_reach_full_4x4(tuple(grid)):
            return False
    return True

