def get_basis_proper(vectors):
    basis = []
    for v in vectors:
        v = v.astype(np.int64)
        for b in basis:
            idx = np.where(b != 0)[0][0]
            if v[idx] != 0:
                v = np.bitwise_xor(v, b)
        if np.any(v != 0):
            basis.append(v)
            basis.sort(key=lambda x: np.where(x != 0)[0][0])
    return basis

