        vec[i*n : (i+1)*n] = 1
        basis_V_input.append(vec)
    for j in range(n):
        vec = np.zeros(n*n, dtype=int)
        vec[j::n] = 1
        basis_V_input.append(vec)
    basis_V = get_basis_proper(basis_V_input)

    M_basis_input = []
    for i in range(n-1):
        for j in range(n-1):
            vec = np.zeros(n*n, dtype=int)
            vec[i*n + j] = 1
            vec[(i+1)*n + j] = 1
            vec[i*n + (j+1)] = 1
            vec[(i+1)*n + (j+1)] = 1
            M_basis_input.append(vec)
    basis_W = get_basis_proper(M_basis_input)

    max_w = 0
    if n <= 5:
        for a_bits in range(1 << n):
            a = [(a_bits >> i) & 1 for i in range(n)]
            for b_bits in range(1 << n):
                b = [(b_bits >> j) & 1 for j in range(n)]
                x = np.zeros(n*n, dtype=int)
                for i in range(n):
                    for j in range(n):
                        x[i*n + j] = a[i] ^ b[j]
                x_prime = np.zeros(n*n, dtype=int)
                for i in range(n):
                    for j in range(n):
                        x_prime[i*n + j] = (1-a[i]) ^ b[j]

                is_in_W = True
                v_temp = x_prime.astype(np.int64)
                for bw in basis_W:
                    idx = np.where(bw != 0)[0][0]
                    if v_temp[idx] != 0:
                        v_temp = np.bitwise_xor(v_temp, bw)
                if np.any(v_temp != 0):
                    is_in_W = False

                if not is_in_W:
                    max_w = max(max_w, np.sum(x))
        return max_w
    else:
        return 0

